#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


# Run a foreground command the human stops with Ctrl-C, without Ctrl-C also
# ending the wizard (a trap handler, unlike an ignored signal, resets in the child).
_until_ctrl_c() { trap ':' INT; "$@" || true; trap - INT; }

run_wizard() {

TOTAL_STAGES=9
cd "$(dirname "$0")/.."
APP_URL="http://127.0.0.1:8765"
LOG="sessions/wizard-run.log"

banner "Meeting Copilot: run and test (macOS)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Python environment"
say "uv installs Python 3.12 and every dependency from uv.lock."
command -v uv >/dev/null || { warn "uv is missing: curl -LsSf https://astral.sh/uv/install.sh | sh"; exit 1; }
uv sync
pause "Environment ready. Press Enter"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Ollama (local fallback model)"
OLLAMA_MODEL=$(_existing OLLAMA_MODEL || true); OLLAMA_MODEL=${OLLAMA_MODEL:-granite4:7b-a1b-h}
if ! curl -fs http://127.0.0.1:11434/api/tags >/dev/null; then
  warn "Ollama isn't running."
  step "Start the Ollama app (menu bar llama icon), or run 'ollama serve' in another terminal."
  open -a Ollama >/dev/null 2>&1 || true
  pause "Press Enter once Ollama is running"
fi
if ollama list 2>/dev/null | awk '{print $1}' | grep -qx "$OLLAMA_MODEL"; then
  say "Model $OLLAMA_MODEL is installed."
elif confirm "Pull $OLLAMA_MODEL now (a few GB)?"; then
  ollama pull "$OLLAMA_MODEL"
else
  SKIPPED+=("ollama pull $OLLAMA_MODEL (the window warns until a model is there)")
fi
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Speech recognition engine"
say "STT_ENGINE=auto uses WhisperKit (Apple GPU) on Apple Silicon, else faster-whisper."
say "WhisperKit needs Homebrew's whisperkit-cli; without it the app falls back to faster-whisper on the CPU."
if [[ "$(uname -m)" == arm64 ]]; then
  if command -v whisperkit-cli >/dev/null 2>&1; then
    say "whisperkit-cli is installed."
  elif confirm "Install whisperkit-cli with Homebrew?"; then
    brew install whisperkit-cli
  else
    SKIPPED+=("whisperkit-cli: transcription uses faster-whisper on the CPU")
  fi
  note "The first WhisperKit start can take a few minutes while Core ML prepares the model."
else
  say "Not Apple Silicon: faster-whisper is used."
fi
if [[ ! -f "$ENV_FILE" ]]; then cp .env.example "$ENV_FILE"; chmod 600 "$ENV_FILE"; fi
note "STT_ENGINE: auto | whisperkit | faster-whisper"
ask STT_ENGINE "STT_ENGINE:"; write_env STT_ENGINE "${STT_ENGINE:-auto}"
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Unit tests"
say "No audio or GPU needed. All tests should pass."
if uv run pytest -q; then say "Tests passed."
else warn "Some tests failed (output above)."; confirm "Continue anyway?" || exit 1; fi
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Configure .env"
if [[ ! -f "$ENV_FILE" ]]; then cp .env.example "$ENV_FILE"; chmod 600 "$ENV_FILE"; say "Created .env from .env.example."; fi
note "Providers: gemini | claude | openai | grok | custom | ollama (local only, no key)"
ask LLM_PROVIDER "LLM_PROVIDER:"
case "$LLM_PROVIDER" in
  gemini) open_url "https://aistudio.google.com/apikey"
          step "Create API key → copy it. Enable billing: the free tier is ~20 requests/day."
          ask_secret GEMINI_API_KEY "Paste GEMINI_API_KEY:"; write_env GEMINI_API_KEY "$GEMINI_API_KEY" ;;
  claude) open_url "https://console.anthropic.com/settings/keys"
          step "Create Key → name it → copy it (shown once)."
          ask_secret ANTHROPIC_API_KEY "Paste ANTHROPIC_API_KEY:"; write_env ANTHROPIC_API_KEY "$ANTHROPIC_API_KEY" ;;
  openai) open_url "https://platform.openai.com/api-keys"
          step "Create new secret key → copy it (shown once)."
          ask_secret OPENAI_API_KEY "Paste OPENAI_API_KEY:"; write_env OPENAI_API_KEY "$OPENAI_API_KEY" ;;
  grok)   open_url "https://console.x.ai"
          step "API Keys → Create API key → copy it."
          ask_secret XAI_API_KEY "Paste XAI_API_KEY:"; write_env XAI_API_KEY "$XAI_API_KEY" ;;
  custom) ask CUSTOM_BASE_URL "CUSTOM_BASE_URL (e.g. http://localhost:20128/v1):"; write_env CUSTOM_BASE_URL "$CUSTOM_BASE_URL"
          ask CUSTOM_MODEL "CUSTOM_MODEL:"; write_env CUSTOM_MODEL "$CUSTOM_MODEL"
          ask_secret CUSTOM_API_KEY "CUSTOM_API_KEY (Enter for none):"; write_env CUSTOM_API_KEY "$CUSTOM_API_KEY" ;;
  ollama) say "Local only: no key needed." ;;
  *)      warn "Unknown provider '$LLM_PROVIDER'; using ollama."; LLM_PROVIDER=ollama ;;
esac
write_env LLM_PROVIDER "$LLM_PROVIDER"
note "PROMPT: system (client/sales calls) | interview (job interviews, meetings at work)"
ask PROMPT "PROMPT:"; write_env PROMPT "$PROMPT"
note "LANGUAGES: spoken languages, yours first, e.g. en,ar or de,en"
ask LANGUAGES "LANGUAGES:"; write_env LANGUAGES "$LANGUAGES"
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "BlackHole: capture the meeting audio"
say "macOS has no system-audio loopback; BlackHole 2ch is a virtual device the app records from."
# Installed = the driver is on disk; loaded = Core Audio lists it (only after coreaudiod restarts).
bh_loaded() { system_profiler SPAudioDataType 2>/dev/null | grep -q "BlackHole"; }
BH_DRIVER="/Library/Audio/Plug-Ins/HAL/BlackHole2ch.driver"
if bh_loaded; then
  say "BlackHole is installed and loaded."
else
  if [[ -d "$BH_DRIVER" ]]; then
    say "BlackHole is installed, but Core Audio hasn't loaded it yet."
  elif confirm "Install BlackHole 2ch with Homebrew (asks for your Mac password)?"; then
    brew install --cask blackhole-2ch
  else
    SKIPPED+=("BlackHole: without it only your mic is transcribed")
  fi
  if [[ -d "$BH_DRIVER" ]]; then
    say "Core Audio must restart to load the driver; sound cuts out for a second."
    if confirm "Restart Core Audio now (sudo killall coreaudiod, asks for your Mac password)?"; then
      sudo killall coreaudiod || true
      sleep 3
    fi
    if bh_loaded; then
      say "BlackHole is loaded."
    else
      warn "Core Audio still doesn't list BlackHole. Restart the Mac, then re-run this wizard."
      SKIPPED+=("BlackHole not loaded: restart the Mac, then check with uv run python -m copilot.devices")
      confirm "Continue without the meeting audio?" || exit 1
    fi
  fi
fi
step "Audio MIDI Setup opens. Click + (bottom left) → Create Multi-Output Device."
step "Tick your headphones/speakers AND BlackHole 2ch."
step "Primary Device: your headphones. Tick Drift Correction on BlackHole 2ch only."
open -a "Audio MIDI Setup" || true
pause "Press Enter once the Multi-Output Device exists"
open_url "x-apple.systempreferences:com.apple.Sound-Settings.extension"
step "System Settings → Sound → Output: select Multi-Output Device."
note "Volume keys don't work on a Multi-Output Device; set the volume on the headphones in Audio MIDI Setup."
pause "Press Enter once the output is switched"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Microphone access and live levels"
open_url "x-apple.systempreferences:com.apple.preference.security?Privacy_Microphone"
step "Privacy & Security → Microphone: allow your terminal app (it may ask on first use)."
pause "Press Enter to show the device list and live meters"
say "Speak: the User bar should move. Play any video: the Participant bar should move."
say "Press Ctrl-C when both bars react."
_until_ctrl_c uv run python -m copilot.devices
printf '\n'
note "Use a part of a device name from the list above; Enter keeps the current value."
ask MIC_DEVICE "MIC_DEVICE (empty = system default):"; write_env MIC_DEVICE "$MIC_DEVICE"
ask LOOPBACK_DEVICE "LOOPBACK_DEVICE (empty = BlackHole):"; write_env LOOPBACK_DEVICE "$LOOPBACK_DEVICE"
confirm "Did both bars react?" || SKIPPED+=("audio levels: check devices with uv run python -m copilot.devices")

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Live run"
mkdir -p sessions
say "Starting the app (output: $LOG). The first run downloads the Whisper model."
LOG_START=$(( $( (wc -l < "$LOG") 2>/dev/null || echo 0) + 1 ))
uv run python -m copilot --log "$LOG" & APP_PID=$!
# Background jobs ignore SIGINT, so stop the app with SIGTERM, also on an early exit.
trap 'kill -TERM "$APP_PID" 2>/dev/null || true' EXIT
for _ in $(seq 1 120); do
  curl -fs "$APP_URL" >/dev/null 2>&1 && break
  kill -0 "$APP_PID" 2>/dev/null || { warn "The app exited. Last log lines:"; tail -n 20 "$LOG"; exit 1; }
  sleep 1
done
say "The window should be open at $APP_URL (open it yourself if not)."
step "Click 'Meeting starten'. The header shows the AI engine; no red warning."
step "Speak a sentence: a [User] line appears in the transcript."
step "Play a video with speech: [Participant] lines appear."
step "After the speaker pauses, a suggestion card appears."
step "Click 'Was soll ich jetzt antworten?': an answer card appears."
step "Click 'Übersetzen': lines get a translation."
step "Click 'Meeting beenden': 'Meeting gespeichert' shows."
pause "Press Enter when done, to stop the app"
kill -TERM "$APP_PID" 2>/dev/null || true
wait "$APP_PID" 2>/dev/null || true
trap - EXIT
say "App stopped. STT engine used in this run:"
tail -n +"$LOG_START" "$LOG" | grep "STT:" | sed 's/^/    /' || warn "no STT lines in $LOG (did the meeting start?)"
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Meeting record"
MEETINGS=$(_existing MEETINGS_DIR || true); MEETINGS=${MEETINGS:-meetings}
LATEST=$(ls -t "$MEETINGS"/Meeting*.md 2>/dev/null | head -n1 || true)
if [[ -n "$LATEST" ]]; then
  say "Latest record: $LATEST"
  note "It should hold a summary, facts, suggestions and the transcript."
  open "$LATEST" || true
  confirm "Does it look right?" || SKIPPED+=("meeting record looked wrong: $LATEST, log: $LOG")
else
  warn "No meeting record in $MEETINGS/."
  SKIPPED+=("no meeting record written; check $LOG")
fi

finish
say "Run again any time: uv run python -m copilot"
}

run_wizard "$@"; exit
